{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Mithramycin, a glycosylated natural product, achieved only a 0.12 CSF:plasma ratio in monkeys with little brain distribution, directly demonstrating poor CNS access for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Navtemadlin had a brain Kp of 0.009 in mice due primarily to P-gp efflux, showing that efflux can exclude even relatively lipophilic molecules from the brain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Digitoxin, a lipophilic cardiac glycoside, showed a very low CSF/plasma ratio of 0.01-0.03 in dogs, indicating glycosidic structure and efflux limit brain penetration despite lipophilicity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Epimedin B was the least concentrated compound in rat brain in a tissue distribution study, demonstrating that glycosylated polyphenols hardly cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "DIFEQ showed very low brain uptake (0.003% of injected dose) in mice and was characterized as having poor uptake, providing direct in vivo evidence of negligible CNS access for a polar glycoside.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental evidence indicates that glycosylated, polyhydroxylated natural products with efflux liability are excluded from the CNS; the query's amino-sugar anthracycline structure shares these features and is predicted to have inadequate brain access.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the query molecule itself.",
    "No transporter-inhibition or P-gp knockout data for the query.",
    "No human CNS exposure data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

